-- trang đầu
SELECT id, created_at, title FROM posts ORDER BY created_at DESC, id DESC LIMIT 20;

-- trang kế, truyền created_at và id của dòng cuối
SELECT id, created_at, title FROM posts
WHERE (created_at, id) < ('2026-11-10 08:00:00', 4821)
ORDER BY created_at DESC, id DESC LIMIT 20;

CREATE INDEX ON posts (created_at DESC, id DESC);
